-- Display names of Safenet Sentinels and validators. Generated by `npm run sync:participants`
-- from github.com/safe-fndn/safenet-data at commit 88bf9d92301b43b350e96edc28c21f059dbad667; do not edit by hand.
-- Labels only: a row here does not mean the address is a current participant. Membership comes
-- from onchain events. Join on address (varbinary) and fall back to the address when no row matches:
--   coalesce(l.label, '0x' || lower(to_hex(x.address)))

select role, address, label
from (
    values
    ('sentinel', 0x101d59dbb8c5e70f45d52634f23800fca4fbe031, 'OpenCover'),
    ('sentinel', 0x6d081448c04d9ef7cf8ecf54207b1931ecc25312, 'Candide'),
    ('sentinel', 0xb28eb357bfa420c17bae3e6bfdb50094fb5babf2, 'IntentGuard'),
    ('sentinel', 0xc84a0928632382e75c543acced101b9525027362, 'BlockSec'),
    ('validator', 0x3d58a5475c1336b0a755c3abd298ceb9b7bb9cde, 'Gnosis'),
    ('validator', 0x7b0a8efa45de81f11f2846ec28259b62155a2b37, 'Greenfield'),
    ('validator', 0xb0e735d4a3b70195420e0ae933689a55750cfcd2, 'RockawayX'),
    ('validator', 0xcc00de0ea14c08669b26dcbfe365dbd9890b04d9, 'Core Contributors'),
    ('validator', 0xd8997c2a94052c4fb79b53b3e255c1f07c99305b, 'Blockchain Capital'),
    ('validator', 0xf6ea21d702983c443f58a267265912fe03d2ff0b, 'Safe Labs')
) as t (role, address, label)
